PRAGMA foreign_keys = ON;
CREATE TABLE desks(desk_id TEXT PRIMARY KEY, name TEXT NOT NULL, business TEXT NOT NULL);
CREATE TABLE traders(trader_id TEXT PRIMARY KEY, desk_id TEXT NOT NULL REFERENCES desks, name TEXT NOT NULL);
CREATE TABLE accounts(account_id TEXT PRIMARY KEY, name TEXT NOT NULL, account_type TEXT NOT NULL CHECK(account_type IN ('internal','institutional')), purpose TEXT NOT NULL);
CREATE TABLE securities(security_id TEXT PRIMARY KEY, symbol TEXT NOT NULL UNIQUE, issuer TEXT NOT NULL, sector TEXT NOT NULL, liquidity_tier TEXT NOT NULL);
CREATE TABLE sessions(session_date TEXT PRIMARY KEY, open_at TEXT NOT NULL, close_at TEXT NOT NULL CHECK(close_at > open_at));
CREATE TABLE mandates(mandate_id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts, security_id TEXT NOT NULL REFERENCES securities, side TEXT NOT NULL CHECK(side IN ('buy','sell')), quantity INTEGER NOT NULL CHECK(quantity>0), window_start TEXT NOT NULL, window_end TEXT NOT NULL CHECK(window_end>window_start), signed_at TEXT NOT NULL, ingested_at TEXT NOT NULL, source_record_id TEXT NOT NULL);
CREATE TABLE orders(order_id TEXT PRIMARY KEY, trader_id TEXT NOT NULL REFERENCES traders, account_id TEXT NOT NULL REFERENCES accounts, security_id TEXT NOT NULL REFERENCES securities, submitted_at TEXT NOT NULL, side TEXT NOT NULL CHECK(side IN ('buy','sell')), original_quantity INTEGER NOT NULL CHECK(original_quantity>0), limit_price_cents INTEGER NOT NULL CHECK(limit_price_cents>0), mandate_id TEXT REFERENCES mandates, claimed_instruction_at TEXT);
CREATE TABLE order_events(event_id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders, event_type TEXT NOT NULL CHECK(event_type IN ('accepted','amended','filled','cancelled')), event_at TEXT NOT NULL, ingested_at TEXT NOT NULL CHECK(ingested_at>=event_at), total_quantity INTEGER NOT NULL CHECK(total_quantity>0), limit_price_cents INTEGER NOT NULL CHECK(limit_price_cents>0));
CREATE TABLE fills(fill_id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders, executed_at TEXT NOT NULL, ingested_at TEXT NOT NULL CHECK(ingested_at>=executed_at), quantity INTEGER NOT NULL CHECK(quantity>0), price_cents INTEGER NOT NULL CHECK(price_cents>0), venue_id TEXT NOT NULL);
CREATE TABLE market_bars(security_id TEXT NOT NULL REFERENCES securities, minute_at TEXT NOT NULL, open_cents INTEGER NOT NULL, high_cents INTEGER NOT NULL, low_cents INTEGER NOT NULL, close_cents INTEGER NOT NULL, market_volume_shares INTEGER NOT NULL CHECK(market_volume_shares>0), PRIMARY KEY(security_id,minute_at), CHECK(low_cents<=open_cents AND open_cents<=high_cents AND low_cents<=close_cents AND close_cents<=high_cents));
CREATE TABLE market_daily(security_id TEXT NOT NULL REFERENCES securities, session_date TEXT NOT NULL, open_cents INTEGER NOT NULL, high_cents INTEGER NOT NULL, low_cents INTEGER NOT NULL, close_cents INTEGER NOT NULL, volume_shares INTEGER NOT NULL CHECK(volume_shares>0), source_url TEXT NOT NULL, retrieved_at TEXT NOT NULL, response_sha256 TEXT NOT NULL, price_basis TEXT NOT NULL, PRIMARY KEY(security_id,session_date));
CREATE TABLE evidence(evidence_id TEXT PRIMARY KEY, kind TEXT NOT NULL, event_at TEXT NOT NULL, available_at TEXT NOT NULL, ingested_at TEXT NOT NULL, source_system TEXT NOT NULL, source_record_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('available','unavailable','access_denied')), content TEXT NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE evidence_scope(evidence_id TEXT NOT NULL REFERENCES evidence, account_id TEXT NOT NULL REFERENCES accounts, PRIMARY KEY(evidence_id,account_id));
CREATE TABLE alerts(alert_id TEXT PRIMARY KEY, source_event_id TEXT NOT NULL UNIQUE, rule TEXT NOT NULL, detected_at TEXT NOT NULL, cutoff_at TEXT NOT NULL CHECK(cutoff_at>=detected_at), account_id TEXT NOT NULL REFERENCES accounts);
CREATE TABLE alert_orders(alert_id TEXT NOT NULL REFERENCES alerts, order_id TEXT NOT NULL REFERENCES orders, PRIMARY KEY(alert_id,order_id));
CREATE INDEX fills_by_order_time ON fills(order_id,executed_at);
CREATE INDEX orders_by_subject_time ON orders(trader_id,security_id,submitted_at);
CREATE INDEX evidence_by_availability ON evidence(available_at,ingested_at);
